async function runDemoLoad(log){const stages=[],run='load'+Date.now();let counter=0,seed=42;const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};
 for(const [count,rate] of [[1000,100],[3000,500],[6000,1000]]){const start=performance.now(),latencies=[];let requests=0,accepted=0,errors=0,transport=0;
 for(let done=0;done<count;done+=100){if(performance.now()-start>60000)throw Error('Stage deadline reached');const target=start+done/rate*1000;if(target>performance.now())await new Promise(r=>setTimeout(r,target-performance.now()));const timestamp=new Date().toISOString(),records=Array.from({length:Math.min(100,count-done)},()=>({record_id:run+'_'+counter++,source_id:'src'+String(counter%10+1).padStart(2,'0'),timestamp,anomaly_score:random()}));const t=performance.now();requests++;try{const r=await fetch('/giang-aiot/v1/batch',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({records}),signal:AbortSignal.timeout(3000)});const data=await r.json();latencies.push(performance.now()-t);accepted+=data.summary?.accepted||0;errors+=data.summary?.errors||0;if(r.status!==200||data.summary?.accepted!==records.length)transport++;}catch(e){transport++;}if(transport>0)break;}
 const seconds=(performance.now()-start)/1000;latencies.sort((a,b)=>a-b);const result={target_records:count,target_records_per_second:rate,requests,accepted,record_errors:errors,unexpected_request_errors:transport,elapsed_seconds:seconds,records_per_second:accepted/seconds,requests_per_second:requests/seconds,median_ms:latencies.length%2?latencies[Math.floor(latencies.length/2)]:(latencies[latencies.length/2-1]+latencies[latencies.length/2])/2,p95_ms:latencies[Math.max(0,Math.ceil(latencies.length*.95)-1)]||0,unexpected_request_error_rate:transport/requests};stages.push(result);log(JSON.stringify(result));if(transport)break;}return {mode:'real HTTP from browser, simulated data; batch=100, concurrency=1',seed:42,stages};}

